public List<List<Integer>> permute(int[] nums){
    java.util.List<List<Integer>> res = new java.util.ArrayList<>();
    int n = nums.length;
    if(n == 0){
        return res;
    }
    int[] a = java.util.Arrays.copyOf(nums, n);
    java.util.Arrays.sort(a);
    boolean hasNext = true;
    while(hasNext){
        java.util.List<Integer> temp = new java.util.ArrayList<>(n);
        for(int val : a){
            temp.add(val);
        }
        res.add(temp);
        int i = n - 2;
        while(i >= 0 && a[i] >= a[i+1]) i--;
        if(i < 0){
            hasNext = false;
            break;
        }
        int j = n - 1;
        while(a[j] <= a[i]) j--;
        int swap = a[i];
        a[i] = a[j];
        a[j] = swap;
        int l = i + 1, r = n - 1;
        while(l < r){
            int t = a[l];
            a[l] = a[r];
            a[r] = t;
            l++; r--;
        }
    }
    return res;
}

