public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    // Frequency map for all numbers
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int count = 0;
    for (int num : numbers) {
        if (num % 2 != 0) {
            continue; // cannot be twice an integer
        }
        int target = num / 2;
        Integer targetCount = freq.get(target);
        if (targetCount == null) {
            continue; // target not present
        }
        if (num == target) {
            // target is same as num => requires at least two occurrences
            if (targetCount >= 2) {
                count++;
            }
        } else {
            count++;
        }
    }
    return count;
}

