public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate basic parameters
    if (n <= 0 || start == null || end == null || paths == null) {
        throw new IllegalArgumentException("Invalid input: n, start, end, or paths is null or n <= 0");
    }
    int dim = start.length;
    if (dim == 0 || end.length != dim) {
        throw new IllegalArgumentException("Start and end coordinates must have the same non‑zero dimension");
    }
    // Helper to convert coordinate to a string key
    java.util.function.Function<int[], String> coordKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };
    // Map coordinate key to unique node id
    java.util.Map<String, Integer> idMap = new java.util.HashMap<>();
    java.util.List<int[]> nodes = new java.util.ArrayList<>();
    // Function to get or create id
    java.util.function.Function<int[], Integer> getId = coord -> {
        String key = coordKey.apply(coord);
        if (!idMap.containsKey(key)) {
            int id = idMap.size();
            idMap.put(key, id);
            nodes.add(coord);
        }
        return idMap.get(key);
    };
    // Get ids for start and end
    int startId = getId.apply(start);
    int endId = getId.apply(end);
    // Build adjacency list
    int size = 0;
    java.util.ArrayList<java.util.ArrayList<Integer>> adj = new java.util.ArrayList<>();
    // Function to ensure adjacency list capacity
    java.util.function.BiConsumer<Integer, Integer> addEdge = (a, b) -> {
        while (adj.size() <= Math.max(a, b)) {
            adj.add(new java.util.ArrayList<>());
        }
        adj.get(a).add(b);
        adj.get(b).add(a);
    };
    // Process paths
    for (int[] path : paths) {
        if (path == null || path.length != 2 * dim) {
            throw new IllegalArgumentException("Each path must contain start and end coordinates of dimension " + dim);
        }
        int[] p1 = new int[dim], p2 = new int[dim];
        System.arraycopy(path, 0, p1, 0, dim);
        System.arraycopy(path, dim, p2, 0, dim);
        int id1 = getId.apply(p1);
        int id2 = getId.apply(p2);
        addEdge.accept(id1, id2);
    }
    // If start equals end
    if (startId == endId) {
        return "can be travelled";
    }
    // BFS to check reachability
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    boolean[] visited = new boolean[adj.size()];
    queue.add(startId);
    visited[startId] = true;
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        java.util.List<Integer> neighbors = adj.get(cur);
        if (neighbors != null) {
            for (int nb : neighbors) {
                if (!visited[nb]) {
                    if (nb == endId) {
                        return "can be travelled";
                    }
                    visited[nb] = true;
                    queue.add(nb);
                }
            }
        }
    }
    return "cannot be travelled";
}

