public boolean canArrange(int[] arr, int k) {
    if (arr == null || k == 0) {
        return false; // invalid divisor
    }
    if (arr.length % 2 != 0) {
        return false; // cannot pair odd number of elements
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int mod = ((num % k) + k) % k;
        freq[mod]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // occurs when k is even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Basic validation
    if (arr == null || k <= 0 || arr.length % 2 != 0) {
        return false;
    }
    try {
        java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
        // Count remainders
        for (int num : arr) {
            int rem = ((num % k) + k) % k; // handle negative numbers
            freq.put(rem, freq.getOrDefault(rem, 0) + 1);
        }
        java.util.HashSet<Integer> visited = new java.util.HashSet<>();
        for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            int r = entry.getKey();
            if (visited.contains(r)) {
                continue;
            }
            int count = entry.getValue();
            if (r == 0 || (k % 2 == 0 && r == k / 2)) {
                // self complementary remainders
                if (count % 2 != 0) {
                    return false;
                }
                visited.add(r);
            } else {
                int comp = (k - r) % k;
                int compCount = freq.getOrDefault(comp, 0);
                if (count != compCount) {
                    return false;
                }
                visited.add(r);
                visited.add(comp);
            }
        }
        return true;
    } catch (Exception e) {
        // In case of any runtime issues, consider arrangement not possible
        return false;
    }
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
