    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, check remainder k/2
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    int limit = k / 2;
    for (int r = 1; r <= limit; r++) {
        if (r == k - r) {
            continue; // Already handled when k is even
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Validate input
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k <= 0) {
        return false;
    }

    // Count occurrences of each remainder modulo k
    int[] remainderCount = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // handle negative numbers
        remainderCount[rem]++;
    }

    // Check remainder 0 group
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    // Check pairs of complementary remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // occurs when k is even and r == k/2
            if (remainderCount[r] % 2 != 0) {
                return false;
            }
        } else {
            if (remainderCount[r] != remainderCount[complement]) {
                return false;
            }
        }
    }

