    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // cannot form n/2 pairs if array size is odd
    }
    int mod = Math.abs(k);
    int[] freq = new int[mod];
    for (int num : arr) {
        int rem = num % mod;
        if (rem < 0) {
            rem += mod;
        }
        freq[rem]++;
    }
    if (freq[0] % 2 != 0) {
        return false; // remainder 0 must appear even number of times
    }
    for (int r = 1; r <= mod / 2; r++) {
        int complement = mod - r;
        if (r == complement) { // when k is even and remainder is k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

