public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 0) return 0;
    // Build adjacency list
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    // DFS to get traversal order and parent of each node
    int[] parent = new int[n];
    Arrays.fill(parent, -1);
    int[] order = new int[n];
    int idx = 0;
    Stack<Integer> stack = new Stack<>();
    stack.push(0);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int nb : graph[node]) {
            if (nb != parent[node]) {
                parent[nb] = node;
                stack.push(nb);
            }
        }
    }
    // Determine if each subtree contains an apple
    boolean[] hasSubApple = new boolean[n];
    for (int i = n - 1; i >= 0; i--) {
        int node = order[i];
        boolean has = hasApple[node];
        for (int nb : graph[node]) {
            if (nb != parent[node] && hasSubApple[nb]) {
                has = true;
            }
        }
        hasSubApple[node] = has;
    }
    // Sum cost: each edge to a node whose subtree has an apple costs 2 (go and return)
    int cost = 0;
    for (int node = 1; node < n; node++) {
        if (hasSubApple[node]) {
            cost += 2;
        }
    }
    return cost;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || hasApple == null || hasApple.length != n || edges == null) {
        return 0;
    }

    @SuppressWarnings("unchecked")
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }

    try {
        for (int[] e : edges) {
            if (e == null || e.length != 2) {
                continue;
            }
            int u = e[0];
            int v = e[1];
            if (u < 0 || u >= n || v < 0 || v >= n) {
                continue;
            }
            adj[u].add(v);
            adj[v].add(u);
        }
    } catch (Exception ignored) {
        // In case of malformed input, return 0
        return 0;
    }

    int[] total = new int[1]; // holds the accumulated cost
    dfs(0, -1, adj, hasApple, total);
    return total[0];
}

private boolean dfs(int node, int parent, List<Integer>[] adj, boolean[] hasApple, int[] total) {
    boolean has = hasApple[node];
    for (int child : adj[node]) {
        if (child == parent) {
