public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.put(c, map.getOrDefault(c, 0) + 1);
    }
    StringBuilder result = new StringBuilder();
    while (!map.isEmpty()) {
        // Ascending phase
        Character last = null;
        boolean first = true;
        while (true) {
            if (first) {
                java.util.Map.Entry<Character, Integer> e = map.firstEntry();
                if (e == null) break;
                char c = e.getKey();
                result.append(c);
                if (e.getValue() == 1) {
                    map.remove(c);
                } else {
                    map.put(c, e.getValue() - 1);
                }
                last = c;
                first = false;
            } else {
                java.util.Map.Entry<Character, Integer> e = map.higherEntry(last);
                if (e == null) break;
                char c = e.getKey();
                result.append(c);
                if (e.getValue() == 1) {
                    map.remove(c);
                } else {
                    map.put(c, e.getValue() - 1);
                }
                last = c;
            }
        }
        // Descending phase
        last = null;
        first = true;
        while (true) {
            if (first) {
                java.util.Map.Entry<Character, Integer> e = map.lastEntry();
                if (e == null) break;
                char c = e.getKey();
                result.append(c);
                if (e.getValue() == 1) {
                    map.remove(c);
                } else {
                    map.put(c, e.getValue() - 1);
                }
                last = c;
                first = false;
            } else {
                java.util.Map.Entry<Character, Integer> e = map.lowerEntry(last);
                if (e == null) break;
                char c = e.getKey();
                result.append(c);
                if (e.getValue() == 1) {
                    map.remove(c);
                } else {
                    map.put(c, e.getValue() - 1);
                }
                last = c;
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int length = s.length();
    if (length == 0) {
        return "";
    }
    // Frequency array for all possible char codes (0-255)
    int[] freq = new int[256];
    for (int i = 0; i < length; i++) {
        freq[s.charAt(i)]++;
    }

    StringBuilder result = new StringBuilder(length);
    int remaining = length;

    while (remaining > 0) {
        // Step 1: pick smallest character
        int current = -1;
        for (int c = 0; c < 256; c++) {
            if (freq[c] > 0) {
                current = c;
                freq[c]--;
                remaining--;
                break;
            }
        }
        if (current == -1) {
            break; // no characters left
        }
        result.append((char) current);
        int last = current;

        // Step 2: pick increasing characters
        while (true) {
            int next = -1;
            for (int c = last + 1; c < 256; c++) {
                if (freq[c] > 0) {
                    next = c;
                    freq[c]--;
                    remaining--;
                    break;
                }
            }
            if (next == -1) {
                break;
            }
            result.append((char) next);
            last = next;
        }

        // Step 4: pick largest remaining character
        if (remaining == 0) {
            break;
        }
        int largest = -1;
        for (int c = 255; c >= 0; c--) {
            if (freq[c] > 0) {
                largest = c;
                freq[c]--;
                remaining--;
                break;
            }
        }
        if (largest == -1) {
            break;
        }
        result.append((char) largest);
        last = largest;

        // Step 5: pick decreasing characters
        while (true) {
            int next = -1;
            for (int c = last - 1; c >= 0; c--) {
                if (freq[c] > 0) {
                    next = c;
                    freq[c]--;
                    remaining--;
                    break;
                }
            }
            if (next == -1) {
                break;
            }
            result.append((char) next);
            last = next;
        }
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (s.isEmpty()) {
        return "";
    }

    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        if (c < 'a' || c > 'z') {
            throw new IllegalArgumentException("String must contain only lowercase letters a-z");
        }
        freq[c - 'a']++;
    }

    StringBuilder result = new StringBuilder(s.length());
    int remaining = s.length();

    while (remaining > 0) {
        // Ascending phase: take smallest to largest characters
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        // Descending phase: take largest to smallest characters
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null) return null;
    if (s.isEmpty()) return "";
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.put(c, map.getOrDefault(c, 0) + 1);
    }
    StringBuilder sb = new StringBuilder();
    while (!map.isEmpty()) {
        // Ascending pass
        Character cur = map.firstKey();
        sb.append(cur);
        int cnt = map.get(cur);
        if (cnt == 1) map.remove(cur);
        else map.put(cur, cnt - 1);
        Character last = cur;
        while (true) {
            Character next = map.higherKey(last);
            if (next == null) break;
            sb.append(next);
            int ccnt = map.get(next);
            if (ccnt == 1) map.remove(next);
            else map.put(next, ccnt - 1);
            last = next;
        }
        // Descending pass
        if (map.isEmpty()) break;
        cur = map.lastKey();
        sb.append(cur);
        cnt = map.get(cur);
        if (cnt == 1) map.remove(cur);
        else map.put(cur, cnt - 1);
        last = cur;
        while (true) {
            Character next = map.lowerKey(last);
            if (next == null) break;
            sb.append(next);
            int ccnt = map.get(next);
            if (ccnt == 1) map.remove(next);
            else map.put(next, ccnt - 1);
            last = next;
        }
    }
    return sb.toString();
}

public String sortString(String s) {
