}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    long total = 0;
    for (int num : nums) {
        total += num;
    }
    int half = n / 2;
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[half + 1];
    for (int i = 0; i <= half; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0);
    int count = 0;
    for (int num : nums) {
        int maxK = Math.min(count, half - 1);
        for (int k = maxK; k >= 0; k--) {
            for (int sum : dp[k]) {
                dp[k + 1].add(sum + num);
            }
        }
        count++;
    }
    for (int k = 1; k <= half; k++) {
        if ((total * k) % n != 0) {
            continue;
        }
        int target = (int) ((total * k) / n);
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

