                for (int sum : dp[size]) {
                    int newSum = sum + num;
                    if (size + 1 == k && newSum == target) {
                        return true;
                    }
                    dp[size + 1].add(newSum);
                }
            }
        }
        if (dp[k].contains(target)) {
            return true;
        }
    }
