}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // dp[i] will hold all possible sums of subsets of size i
    int maxSize = n / 2;
    java.util.ArrayList<java.util.HashSet<Integer>> dp = new java.util.ArrayList<>(maxSize + 1);
    for (int i = 0; i <= maxSize; i++) {
        dp.add(new java.util.HashSet<Integer>());
    }
    dp.get(0).add(0);
    for (int num : nums) {
        // iterate subset sizes backwards to avoid reuse in same iteration
        for (int sz = Math.min(maxSize, n); sz >= 1; sz--) {
            if (sz > maxSize) break;
            java.util.Set<Integer> prevSet = dp.get(sz - 1);
            java.util.Set<Integer> currSet = dp.get(sz);
            for (int s : prevSet) {
                currSet.add(s + num);
            }
        }
    }
    for (int k = 1; k <= maxSize; k++) {
        long prod = (long) totalSum * k;
        if (prod % n != 0) continue;
        int target = (int) (prod / n);
        if (dp.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

