        for (int k = n; k >= 1; k--) {
            if (dp[k - 1] == null) {
                continue;
            }
            if (dp[k] == null) {
                dp[k] = new HashSet<>();
            }
            for (int prevSum : dp[k - 1]) {
                dp[k].add(prevSum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
