}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }
    // Iterate over possible subset sizes from 1 to n/2
    for (int sz = 1; sz <= n / 2; sz++) {
        // The average condition requires that (totalSum * sz) % n == 0
        if ((totalSum * sz) % n != 0) continue;
        int target = (totalSum * sz) / n;
        // dp[k][s] == true if a subset of size k with sum s is achievable
        boolean[][] dp = new boolean[sz + 1][target + 1];
        dp[0][0] = true;
        for (int num : nums) {
            // iterate sizes backwards to avoid using the same number twice in this round
            for (int k = sz; k >= 1; k--) {
                for (int s = target; s >= num; s--) {
                    if (dp[k - 1][s - num]) {
                        dp[k][s] = true;
                    }
                }
            }
            if (dp[sz][target]) return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    try {
        if (cost == null || cost.length == 0) {
            return 0;
        }
        int n = cost.length;
        if (n == 1) {
            // Only one step, we can start above it with no cost
            return 0;
        }
        int prevTwo = cost[0];
        int prevOne = cost[1];
        for (int i = 2; i < n; i++) {
            int current = cost[i] + Math.min(prevOne, prevTwo);
            prevTwo = prevOne;
            prevOne = current;
        }
        return Math.min(prevOne, prevTwo);
    } catch (Exception e) {
        // In case of unexpected errors, return 0 as a safe fallback
        return 0;
    }
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int option1 = dp[i - 1] + cost[i - 1];
        int option2 = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(option1, option2);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        // Can start from step 1 (top) without any cost
        return 0;
    }
    // Only need to keep the last two computed values
    int prevPrev = cost[0];
    int prev = cost[1];
    int current = 0;
    for (int i = 2; i < n; i++) {
        current = cost[i] + Math.min(prev, prevPrev);
        prevPrev = prev;
        prev = current;
    }
    return Math.min(prev, prevPrev);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    // If there is only one step, you can simply start at step 1 instead of paying any cost.
    if (cost.length == 1) {
        return 0;
    }
    int prev = 0; // dp[i-1]
    int curr = 0; // dp[i]
    for (int i = 0; i < cost.length; i++) {
        int next = Math.min(prev, curr) + cost[i];
        prev = curr;
        curr = next;
    }
    return Math.min(prev, curr);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }
    int dpPrevMinus2 = 0; // dp[i-2]
    int dpPrevMinus1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int costFromPrev1 = dpPrevMinus1 + cost[i - 1];
        int costFromPrev2 = dpPrevMinus2 + cost[i - 2];
        int current = Math.min(costFromPrev1, costFromPrev2);
        dpPrevMinus2 = dpPrevMinus1;
        dpPrevMinus1 = current;
    }
    return dpPrevMinus1;
}

