public boolean hasAllCodes(String s, int k) {
    // Basic validation
    if (s == null || k <= 0 || s.length() < k) {
        return false;
    }
    // Ensure k is within manageable bounds to avoid excessive array size
    if (k >= 31) { // 2^k would overflow int and array would be too large
        return false;
    }
    int totalCodes = 1 << k;          // Number of distinct binary strings of length k
    boolean[] seen = new boolean[totalCodes];
    int seenCount = 0;
    int mask = totalCodes - 1;        // Mask to keep only k bits
    int code = 0;
    for (int i = 0; i < s.length(); i++) {
        // Build the current k-bit window
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) { // enough characters to have a full window
            if (!seen[code]) {
                seen[code] = true;
                seenCount++;
                if (seenCount == totalCodes) {
                    return true; // All possible codes found
                }
            }
        }
    }
    return false; // Not all codes appeared
}

public boolean hasAllCodes(String s, int k) {
    try {
        if (s == null || k <= 0) return false;
        int n = s.length();
        if (n < k) return false;

        // Early exit: if number of possible codes exceeds number of substrings
        if (k > 31) return false; // shift would overflow, impossible for given string size
        int totalCodes = 1 << k;
        if (totalCodes > n - k + 1) return false;

        boolean[] seen = new boolean[totalCodes];
        int mask = totalCodes - 1;
        int curr = 0;

        // Build the first window of size k
        for (int i = 0; i < k; i++) {
            curr = ((curr << 1) | (s.charAt(i) - '0')) & mask;
        }
        seen[curr] = true;
        int count = 1;

        // Slide the window across the string
        for (int i = k; i < n; i++) {
            curr = ((curr << 1) | (s.charAt(i) - '0')) & mask;
            if (!seen[curr]) {
                seen[curr] = true;
                count++;
                if (count == totalCodes) {
                    return true;
                }
            }
        }
        return count == totalCodes;
    } catch (Exception e) {
        // In case of any runtime exception (e.g., malformed string characters), return false
        return false;
    }
}

