    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--;
            } else {
                // need a '(' before this ')'
                insertions++;
                // after inserting, the ')' is matched immediately, so balance stays 0
            }
        } else {
            // for safety, ignore unexpected characters
        }
    }
    // close any remaining unmatched '('
    insertions += balance;
    return insertions;
}

