public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int insertions = 0;   // Total number of insertions needed
    int leftNeeded = 0;   // Number of unmatched '('

    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch != '(' && ch != ')') {
            throw new IllegalArgumentException("Input string can only contain '(' and ')'");
        }

        if (ch == '(') {
            leftNeeded++;
        } else { // ch == ')'
            if (leftNeeded > 0) {
                leftNeeded--; // Match with a previous '('
            } else {
                // No unmatched '(' to pair with; need to insert '(' before this ')'
                insertions++;
            }
        }
    }

    // After processing all characters, any remaining unmatched '(' need ')' insertions
    insertions += leftNeeded;
    return insertions;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if ((n & 1) == 0) { // even
        int k = n / 2;
        return k * k;
    } else { // odd
        int k = (n - 1) / 2;
        return k * (k + 1);
    }
}

public int minOperations(int n) {
    if (n <= 0) {
        return 0; // No operations needed for non-positive length
    }
    int half = n / 2;
    if (n % 2 == 0) {
        // n is even: min operations = (n/2)^2
        return half * half;
    } else {
        // n is odd: min operations = floor(n/2) * ceil(n/2)
        return half * (half + 1);
    }
}

