public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }
    int target = n;
    long operations = 0;
    for (int i = 0; i < n; i++) {
        int value = 2 * i + 1;      // arr[i]
        if (value > target) {
            operations += (long) value - target;
        }
    }
    // The problem guarantees that the result fits in an int.
    return (int) operations;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    // The array arr[i] = 2*i + 1 has sum n^2, so each element will become n.
    // The minimal operations equal the total amount that must be moved
    // from elements greater than n to those less than n.
    // This sum is floor(n/2) * ceil(n/2).
    int halfFloor = n / 2;
    int halfCeil = (n + 1) / 2; // ceil for odd n
    return halfFloor * halfCeil;
}

