                int paired = n / i;
                if (paired != i) factors.add(paired);
            }
        }
        Collections.sort(factors);
        return k <= factors.size() ? factors.get(k - 1) : -1;
    } catch (Exception e) {
        return -1;
    }
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    int sqrt = (int)Math.sqrt(n);
    int[] small = new int[sqrt + 1];
    int[] large = new int[sqrt + 1];
    int smallCount = 0;
    int largeCount = 0;
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small[smallCount++] = i;
            int counterpart = n / i;
            if (counterpart != i) {
                large[largeCount++] = counterpart;
            }
        }
    }
    if (k <= smallCount) {
        return small[k - 1];
    }
    int remaining = k - smallCount;
    if (remaining > largeCount) {
        return -1;
    }
    // large array is in reverse order (descending),
    // so we need to get the (remaining-1)-th element from the end
    return large[largeCount - remaining];
}

