                large.add(other);
            }
        }
    }
    // Reverse large to get ascending order
    java.util.Collections.reverse(large);
    java.util.List<Integer> factors = new java.util.ArrayList<>(small);
    factors.addAll(large);
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public String makeGood(String s) {
    if (s == null) {
        return "";
    }
    StringBuilder stack = new StringBuilder();
    try {
        for (char c : s.toCharArray()) {
            int len = stack.length();
            if (len > 0 && Math.abs(stack.charAt(len - 1) - c) == 32) {
                // The current character and the top of the stack cancel each other out
                stack.deleteCharAt(len - 1);
            } else {
                stack.append(c);
            }
        }
        return stack.toString();
    } catch (Exception e) {
        // In case of an unexpected runtime issue, return an empty string
        return "";
    }
}

public String makeGood(String s) {
    if (s == null) return "";
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);
        int len = result.length();
        if (len > 0) {
            char last = result.charAt(len - 1);
            if (Math.abs(current - last) == 32) { // 'a'-'A' = 32
                result.deleteCharAt(len - 1);
                continue;
            }
        }
        result.append(current);
    }
    return result.toString();
}

public String makeGood(String s) {
    try {
        if (s == null) {
            return "";
        }

        java.util.Deque<Character> stack = new java.util.ArrayDeque<>();

        for (char c : s.toCharArray()) {
            if (!stack.isEmpty() && Math.abs(stack.peek() - c) == 32) {
                stack.pop(); // remove opposite case pair
            } else {
                stack.push(c);
            }
        }

        StringBuilder result = new StringBuilder();
        while (!stack.isEmpty()) {
            result.append(stack.removeLast());
        }

        return result.toString();
    } catch (Exception e) {
        // In case of unexpected errors, return empty string as safe fallback
        return "";
    }
}

