private void dfs(int index, java.util.Set<String> used, int count, String s, int[] max) {
    if (index == s.length()) {
        if (count > max[0]) {
            max[0] = count;
        }
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String prefix = s.substring(index, end);
        if (!used.contains(prefix)) {
            used.add(prefix);
            dfs(end, used, count + 1, s, max);
            used.remove(prefix);
        }
    }
