private void backtrack(String s, int pos, java.util.Set<String> seen, int[] best) {
    if (pos == s.length()) {
        best[0] = Math.max(best[0], seen.size());
        return;
    }
    for (int i = pos + 1; i <= s.length(); i++) {
        String sub = s.substring(pos, i);
        if (!seen.contains(sub)) {
            seen.add(sub);
            backtrack(s, i, seen, best);
            seen.remove(sub);
        }
    }
}

public int minOperations(String[] logs) {
    if (logs == null) {
        return 0;
    }
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();
    for (String log : logs) {
        if (log.equals("../")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else if (!log.equals("./")) {
            stack.push(log);
        }
    }
    return stack.size();
}

