            continue;
        }
        if (log.equals("./")) {
            // stay in the same folder, no change
            continue;
        } else if (log.equals("../")) {
            // move up one folder if possible
            if (depth > 0) {
                depth--;
            }
        } else {
            // step into a subfolder
            // For safety we trim any leading/trailing spaces
            String trimmed = log.trim();
            if (!trimmed.isEmpty() && !trimmed.equals("./") && !trimmed.equals("../")) {
                depth++;
            }
        }
    }
    return depth;
}

