public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("Length n must be positive.");
    }
    if (k < n || k > 26 * n) {
        throw new IllegalArgumentException("k must be between n and 26*n inclusive.");
    }
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int needed = k - n;
    int idx = n - 1;
    while (needed > 0 && idx >= 0) {
        int add = Math.min(25, needed);
        result[idx] = (char) ('a' + add);
        needed -= add;
        idx--;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("Length must be positive");
    }
    int minSum = n;          // all 'a's
    int maxSum = 26 * n;     // all 'z's
    if (k < minSum || k > maxSum) {
        throw new IllegalArgumentException("k is out of valid range");
    }

    char[] chars = new char[n];
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }

    int remaining = k - minSum;
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        chars[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(chars);
}

