public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    for (long factor = 1; factor <= n; ) {
        long lower = n % factor;
        long curr = (n / factor) % 10;
        long higher = n / (factor * 10);

        if (curr == 0) {
            count += higher * factor;
        } else if (curr == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }

        if (factor > Long.MAX_VALUE / 10) {
            break; // Prevent overflow
        }
        factor *= 10;
    }
    return (int) count;
}

