    int n = mat[0].length;
    // Ensure all rows have the same length; if not, return 0 or handle gracefully
    for (int i = 0; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            return 0;
        }
    }

    int[][] hor = new int[m][n];     // horizontal
    int[][] ver = new int[m][n];     // vertical
    int[][] diag = new int[m][n];    // main diagonal (\)
    int[][] adiag = new int[m][n];   // anti-diagonal (/)
    int max = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] != 1) {
                continue;
            }
            // Horizontal
            hor[i][j] = (j > 0 ? hor[i][j - 1] : 0) + 1;
            // Vertical
            ver[i][j] = (i > 0 ? ver[i - 1][j] : 0) + 1;
            // Diagonal
            diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
            // Anti-diagonal
            adiag[i][j] = (i > 0 && j < n - 1 ? adiag[i - 1][j + 1] : 0) + 1;

            int localMax = Math.max(Math.max(hor[i][j], ver[i][j]),
                                   Math.max(diag[i][j], adiag[i][j]));
            if (localMax > max) {
                max = localMax;
            }
        }
    }

    return max;
}

