public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int rows = mat.length;
    int cols = mat[0].length;
    // dp[i][j][0] - horizontal (left)
    // dp[i][j][1] - vertical (up)
    // dp[i][j][2] - diagonal (top-left)
    // dp[i][j][3] - anti-diagonal (top-right)
    int[][][] dp = new int[rows][cols][4];
    int maxLen = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                int left = (j > 0 ? dp[i][j - 1][0] : 0) + 1;
                int up = (i > 0 ? dp[i - 1][j][1] : 0) + 1;
                int diag = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1;
                int anti = (i > 0 && j < cols - 1 ? dp[i - 1][j + 1][3] : 0) + 1;

                dp[i][j][0] = left;
                dp[i][j][1] = up;
                dp[i][j][2] = diag;
                dp[i][j][3] = anti;

                int cellMax = Math.max(Math.max(left, up), Math.max(diag, anti));
                if (cellMax > maxLen) {
                    maxLen = cellMax;
                }
            } else {
                // ensuring the dp cell stays with zeros if mat[i][j] is 0
                dp[i][j][0] = dp[i][j][1] = dp[i][j][2] = dp[i][j][3] = 0;
            }
        }
    }
    return maxLen;
}

