    int n = A.length;
    if (n == 0) return 1;
    java.util.Arrays.sort(A);
    int allMask = (1 << n) - 1;
    // Memoization table: dp[mask][lastIndex], -1 means uncomputed
    int[][] dp = new int[1 << n][n];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(dp[i], -1);
    }

    java.util.function.Function<Integer, Integer> isSquare = (sum) -> {
        int sqrt = (int) Math.round(Math.sqrt(sum));
        return sqrt * sqrt == sum ? 1 : 0;
    };

    java.util.function.IntUnaryOperator dfs = new java.util.function.IntUnaryOperator() {
        @Override
        public int applyAsInt(int maskLast) {
            int mask = maskLast >>> 4;
            int last = maskLast & 0xF;
            if (dp[mask][last] != -1) return dp[mask][last];
            if (mask == allMask) return dp[mask][last] = 1;
            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                if (mask != 0 && isSquare.applyAsInt(A[last] + A[i]) == 0) continue;
                int newMask = mask | (1 << i);
                int key = (newMask << 4) | i;
                count += dfs.applyAsInt(key);
            }
            return dp[mask][last] = count;
        }
    };

    int result = 0;
    for (int i = 0; i < n; i++) {
        if (i > 0 && A[i] == A[i - 1] && (1 << (i - 1)) == 0) continue; // skip duplicate starts
        int mask = (1 << i);
        int key = (mask << 4) | i;
        result += dfs.applyAsInt(key);
    }
    return result;
}

