    int n = A.length;
    if (n == 0) return 0;
    Arrays.sort(A);
    boolean[] visited = new boolean[n];
    int[] result = {0};
    dfs(A, visited, -1, result, n);
    return result[0];
}

private static void dfs(int[] A, boolean[] visited, int last, int[] result, int n) {
    if (last == n - 1) {
        result[0] += 1;
        return;
    }
    for (int i = 0; i < n; i++) {
        if (visited[i]) continue;
        // Skip duplicates to avoid identical permutations
        if (i > 0 && A[i] == A[i - 1] && !visited[i - 1]) continue;
        if (last != -1) {
            int sum = A[last] + A[i];
            int root = (int) Math.sqrt(sum);
            if (root * root != sum) continue;
        }
        visited[i] = true;
        dfs(A, visited, i, result, n);
        visited[i] = false;
    }
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && currentHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

