public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the pivot (the first digit from the right that is smaller than its next digit)
    int pivot = len - 2;
    while (pivot >= 0 && digits[pivot] >= digits[pivot + 1]) {
        pivot--;
    }
    if (pivot < 0) {
        // Digits are in descending order: no larger permutation exists
        return -1;
    }

    // Step 2: Find the rightmost successor to the pivot in the suffix
    int successor = len - 1;
    while (digits[successor] <= digits[pivot]) {
        successor--;
    }

    // Step 3: Swap pivot and successor
    char temp = digits[pivot];
    digits[pivot] = digits[successor];
    digits[successor] = temp;

    // Step 4: Reverse the suffix starting at pivot + 1
    int left = pivot + 1;
    int right = len - 1;
    while (left < right) {
        char tmp = digits[left];
        digits[left] = digits[right];
        digits[right] = tmp;
        left++;
        right--;
    }

    // Convert back to integer, handling potential overflow
    try {
        long value = Long.parseLong(new String(digits));
        if (value > Integer.MAX_VALUE) {
            return -1;
        }
        return (int) value;
    } catch (NumberFormatException e) {
        return -1;
    }
}

