    generate(0, current, n, pairs, result);
    return result;
}

private static void generate(int pos, char[] current, int n, char[][] pairs, List<String> result) {
    // Stop when the first half (and middle if odd) is filled
    if (pos >= (n + 1) / 2) {
        // Leading zero is not allowed for numbers with more than one digit
        if (n > 1 && current[0] == '0') {
            return;
        }
        result.add(new String(current));
        return;
    }

    for (char[] pair : pairs) {
        char left = pair[0];
        char right = pair[1];

        // Skip leading zero for multi‑digit numbers
        if (pos == 0 && left == '0' && n > 1) {
            continue;
        }

        current[pos] = left;
        current[n - 1 - pos] = right;
        generate(pos + 1, current, n, pairs, result);
    }
}

