private static List<String> build(int cur, int total) {
    if (cur == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (cur == 1) {
        List<String> base = new ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }
    List<String> mid = build(cur - 2, total);
    List<String> res = new ArrayList<>();
    for (String s : mid) {
        if (cur != total) {
            res.add("0" + s + "0");
        }
        res.add("1" + s + "1");
        res.add("6" + s + "9");
        res.add("8" + s + "8");
        res.add("9" + s + "6");
    }
    return res;
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new ArrayList<>();
    }
    List<String> prev = new ArrayList<>();
    prev.add(""); // base case for length 0
    for (int len = 1; len <= n; len++) {
        List<String> curr = new ArrayList<>();
        if (len == 1) {
            curr.add("0");
            curr.add("1");
            curr.add("8");
        } else {
            for (String inner : prev) {
                if (len != n) { // avoid leading zero when len == n and n > 1
                    curr.add("0" + inner + "0");
                }
                curr.add("1" + inner + "1");
                curr.add("6" + inner + "9");
                curr.add("8" + inner + "8");
                curr.add("9" + inner + "6");
            }
        }
        prev = curr;
    }
    return prev;
}

public static boolean isBoomerang(int[][] points) {
    try {
        if (points == null || points.length != 3) {
            return false;
        }
        // Ensure each point has exactly two coordinates
        for (int[] p : points) {
            if (p == null || p.length != 2) {
                return false;
            }
        }
        // Check for duplicate points
        if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
            (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
            (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
            return false;
        }
        int x1 = points[0][0], y1 = points[0][1];
        int x2 = points[1][0], y2 = points[1][1];
        int x3 = points[2][0], y3 = points[2][1];
        // Use cross product to determine collinearity
        int cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
        return cross != 0;
    } catch (Exception e) {
        // If any unexpected issue occurs, treat as not a boomerang
        return false;
    }
}

