public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int cur = 1;
    for (int i = 0; i < n; i++) {
        result.add(cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else {
            while (cur % 10 == 9 || cur + 1 > n) {
                cur /= 10;
            }
            cur++;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(n);
    if (n < 1) {
        return result;
    }
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        // Try to go deeper (current*10) if it does not exceed n.
        if ((long) current * 10 <= n) {
            current *= 10;
        } else {
            // If we cannot go deeper, we need to find the next number in lexicographic order.
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    if (current > n / 10) {
        return;
    }
    for (int i = 0; i <= 9; i++) {
        long next = (long) current * 10 + i;
        if (next > n) {
            break;
        }
        dfs((int) next, n, result);
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    long cur = 1;
    while (result.size() < n) {
        result.add((int) cur);
        if (cur <= n / 10) {
            cur *= 10;
        } else if (cur % 10 != 9 && cur + 1 <= n) {
            cur += 1;
        } else {
            while (cur / 10 > 0 && (cur / 10) % 10 == 9) {
                cur /= 10;
            }
            cur = (cur / 10) + 1;
        }
    }
    return result;
}

