    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
            }
        }
    }
    return dp[n];
}

