        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return s;
    }
    StringBuilder result = new StringBuilder(n);
    int wordStart = -1; // index of start of current word
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            if (wordStart != -1) {
                // reverse the word from wordStart to i-1
                for (int j = i - 1; j >= wordStart; j--) {
                    result.append(s.charAt(j));
                }
                wordStart = -1;
            }
            result.append(' '); // keep the space
        } else {
            if (wordStart == -1) {
                wordStart = i; // start of a new word
            }
        }
    }
    // Append the last word if the string does not end with a space
    if (wordStart != -1) {
        for (int j = n - 1; j >= wordStart; j--) {
            result.append(s.charAt(j));
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder currentWord = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(currentWord.reverse());
            result.append(' ');
            currentWord.setLength(0);
        } else {
            currentWord.append(c);
        }
    }
    // Append the last word (if any) after reversing
    result.append(currentWord.reverse());
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    int len = s.length();
    StringBuilder result = new StringBuilder(len);
    int i = 0;
    while (i < len) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(' ');
            i++;
        } else {
            int start = i;
            while (i < len && s.charAt(i) != ' ') {
                i++;
            }
            // reverse word from start to i-1
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    try {
        if (s == null) {
            return null;
        }
        if (s.isEmpty()) {
            return s;
        }
        String[] words = s.split(" ");
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            StringBuilder reversed = new StringBuilder();
            for (int j = word.length() - 1; j >= 0; j--) {
                reversed.append(word.charAt(j));
            }
            result.append(reversed);
            if (i < words.length - 1) {
                result.append(" ");
            }
        }
        return result.toString();
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return the original string
        return s;
    }
}

